#include <iostream>
using namespace std;
int main() {
    int amount;
    cout << "Enter amount (>1000):";
    cin >> amount;
    if (amount <= 1000) {
        cout << "Amount should be greater than 1000.";
        return 1;
    }
    int notes = 0;
    int denominations[] = {1000, 500, 100, 50, 20, 10, 5, 1};
    int size = sizeof(denominations)/sizeof(denominations[0]);
    for (int i = 0; i < size; i++) {
        notes += amount / denominations[i];
        amount %= denominations[i];
    }
    cout << "Minimum number of currency notes needed" << endl;
    return 0;
}

